 const types=['Instant'],created=[];
 for(const [name,cost]of [['red','{R}'],['blue','{U}'],['colorless','{1}'],['red-blue','{R}{U}']]){const card=put(M,a,def('V69 paid stack color '+name,types,{cost,resolve:async()=>{}}),'hand'),before=total(a);assert.equal(await g.castSpell(a,card),true);assert.equal(total(a),before-M.mv(cost));created.push(g.stack.find(o=>o.card===card));}
